const state = msg.payload;
const ns = msg.data && msg.data.new_state;
const pct = ns && ns.attributes ? ns.attributes.percentage : null;
if (state !== "on") {
    // fan off (or unavailable): LED always-off; color irrelevant
    return [null, { payload: { value: 2 } }];
}
let color;
if (pct === null || pct <= 25) color = 1;      // blue - low
else if (pct <= 50) color = 2;                 // green - medium
else if (pct <= 75) color = 5;                 // yellow - high
else color = 3;                                // red - max
return [{ payload: { value: color } }, { payload: { value: 3 } }];

