// Denise sleep status from the bedroom + master-bath lights.
//   awake        = bedroom light or reading lamp on          -> green
//   winding-down = only bathroom-area lights on              -> orange (ZEN32: yellow)
//   asleep       = all of the above off                      -> red
const on = v => v === "on";
const awake = on(msg.bedroom) || on(msg.reading);
const winding = on(msg.shower) || on(msg.garySink) || on(msg.deniseSink)
    || on(msg.garyCloset) || on(msg.deniseCloset);

// [office ZEN32 button 3, office sink Jasco] color codes
// ZEN32: 2=green 5=yellow 3=red (ZEN32 hardware has no orange)
// Jasco: 4=green 2=orange 1=red
let zen32, sink;
if (awake)        { zen32 = 2; sink = 4; }
else if (winding) { zen32 = 5; sink = 2; }
else              { zen32 = 3; sink = 1; }
return [{ payload: { value: zen32 } }, { payload: { value: sink } }];

// Pass only light.turn_off calls that target the Game light (by entity or device id).
// The Game switch (node 18) has a history of silently staying on: its state in HA
// can go stale, and a burst off-command can be lost in RF congestion. Downstream,
// a direct Z-Wave Set is published after a short delay - no state cache consulted.
const ev = msg.payload && msg.payload.event;
if (!ev || ev.domain !== "light" || ev.service !== "turn_off") return null;
const blob = JSON.stringify(ev.service_data || {});
if (!blob.includes("light.game_game_switch") &&
    !blob.includes("36d6cc4f40cbdfc275f6f63e445457e1")) return null;
return { payload: { value: false } };

// Auto (Cool/Heat) arbiter for the Downstairs zone. While the mode helper is
// in its auto option, the hardware is only ever commanded to cool or heat --
// its native "auto" mode is broken and never used. Switching sides requires
// the room temp to cross the FAR setpoint by BUFFER, and automatic switches
// are rate-limited by DWELL_MS. Re-selecting auto on the dashboard resets
// the dwell and re-commands a side explicitly.
const BUFFER = 1.0;               // degrees F past the far setpoint
const DWELL_MS = 30 * 60 * 1000;  // min gap between automatic side switches
const KEY = "a765_last_switch_downstairs";

const ent = msg.climateEntity || {};
const attrs = ent.attributes || {};
const temp = Number(attrs.current_temperature);
const cool = Number(msg.coolTemp);
const heat = Number(msg.heatTemp);
if (!isFinite(temp) || !isFinite(cool) || !isFinite(heat)) {
    node.status({ fill: "red", shape: "ring", text: "missing temp/setpoints" });
    return null;
}

let side = ent.state === "cool" ? "cool" : ent.state === "heat" ? "heat" : null;
if (msg.reason === "modeEntry") {
    side = null;       // always command a side explicitly on entry
    flow.set(KEY, 0);  // user touched the mode: reset the dwell guard
}

let want = null;
if (side === "cool") {
    if (temp <= heat - BUFFER) want = "heat";
} else if (side === "heat") {
    if (temp >= cool + BUFFER) want = "cool";
} else {
    want = temp >= (cool + heat) / 2 ? "cool" : "heat";
}

if (want !== null) {
    if (side !== null) {  // dwell guard applies to real side switches only
        const now = Date.now();
        const last = flow.get(KEY) || 0;
        if (now - last < DWELL_MS) {
            node.status({ fill: "yellow", shape: "ring", text: "dwell: holding " + side });
            return null;
        }
        flow.set(KEY, now);
    }
    node.status({ fill: "green", shape: "dot", text: want + " @ " + temp });
    return want === "cool" ? [msg, null, null, null] : [null, msg, null, null];
}

if (msg.reason === "setpoint" && side !== null) {
    node.status({ fill: "green", shape: "dot", text: "push " + side + " setpoint" });
    return side === "cool" ? [null, null, msg, null] : [null, null, null, msg];
}
return null;

