// Adopt a wall-unit setpoint change into the Downstairs helper (hardware ->
// helper). Values were re-read AFTER the 20s settle delay. Guards:
// - a setpoint equal to either helper is an echo of our own command
// - a helper that moved <15s ago may not have echoed back yet; adopting
//   now would revert the user's dashboard tap
const ent = msg.climateEntity || {};
const sp = Number((ent.attributes || {}).temperature);
if (!isFinite(sp)) return null;
const cool = Number(msg.coolTemp);
const heat = Number(msg.heatTemp);
if ((isFinite(cool) && Math.abs(sp - cool) < 0.25) ||
    (isFinite(heat) && Math.abs(sp - heat) < 0.25)) return null;
const touched = global.get("downstairs_setpoint_touched") || 0;
if (Date.now() - touched < 15000) {
    node.status({ fill: "yellow", shape: "ring", text: "helper just moved; skip" });
    return null;
}
const clamped = Math.min(85, Math.max(60, sp));
if (ent.state === "cool" && isFinite(cool)) {
    node.status({ fill: "green", shape: "dot", text: "adopt cool " + clamped });
    return [{ payload: { value: clamped } }, null];
}
if (ent.state === "heat" && isFinite(heat)) {
    node.status({ fill: "green", shape: "dot", text: "adopt heat " + clamped });
    return [null, { payload: { value: clamped } }];
}
return null;

