// The Downstairs cool helper just moved. Enforce cool >= heat + GAP by pushing
// the heat helper down (last-touched wins). Clamp at the helper floor; the
// mirror guard then raises cool instead, so the pair converges with the gap.
const GAP = 2.0;
const cool = Number(msg.payload);
const heat = Number(msg.otherTemp);
if (!isFinite(cool) || !isFinite(heat)) return null;
if (heat <= cool - GAP) return null;
const v = Math.max(60, cool - GAP);
if (Math.abs(v - heat) < 0.25) return null;
node.status({ fill: "green", shape: "dot", text: "heat -> " + v });
return { payload: { value: v } };

